local TowelRackMaker = {}
local PRODUCTS = {
    iron_towelrack = { name = "Železni vešalka za brisače", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni vešalka za brisače za kopališča." },
    bronze_towelrack = { name = "Bronast vešalka za brisače", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast vešalka za brisače za kopališča." },
    silver_towelrack = { name = "Srebrn vešalka za brisače", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn vešalka za brisače za kopališča." },
    gilded_towelrack = { name = "Pozlačen vešalka za brisače", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen vešalka za brisače za kopališča." },
    jewel_set_towelrack = { name = "Draguljast vešalka za brisače", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast vešalka za brisače za kopališča." },
    royal_sovereign_towelrack = { name = "Kraljevski suveren vešalka za brisače", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren vešalka za brisače z biseri za krono." },
}
local BUILDINGS = {
    towelrack_workshop = { name = "Towelrack delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    towelrack_house = { name = "Towelrack hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_towelrack_atelier = { name = "Mojstrski towelrack atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_towelrack_palace = { name = "Suverena towelrack palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
TowelRackMaker.ironStock = 12; TowelRackMaker.bronzeStock = 10; TowelRackMaker.woodStock = 16; TowelRackMaker.leatherStock = 10; TowelRackMaker.silverStock = 8; TowelRackMaker.goldStock = 6; TowelRackMaker.jewelStock = 4; TowelRackMaker.pearlStock = 4
TowelRackMaker.productStock = {}; TowelRackMaker.buildings = {}; TowelRackMaker.maker = nil; TowelRackMaker.activeMaking = {}; TowelRackMaker.totalProducts = 0; TowelRackMaker.dayTimer = 0
function TowelRackMaker.init() TowelRackMaker.ironStock=12; TowelRackMaker.bronzeStock=10; TowelRackMaker.woodStock=16; TowelRackMaker.leatherStock=10; TowelRackMaker.silverStock=8; TowelRackMaker.goldStock=6; TowelRackMaker.jewelStock=4; TowelRackMaker.pearlStock=4; TowelRackMaker.productStock={}; TowelRackMaker.buildings={}; TowelRackMaker.maker=nil; TowelRackMaker.activeMaking={}; TowelRackMaker.totalProducts=0; TowelRackMaker.dayTimer=0; print("[TowelRackMaker] Royal Towel Rack Maker System initialized (6 products, 4 buildings)") end
function TowelRackMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; TowelRackMaker.maker={name=n or ("Vešalkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vešalkar najet: %s (spretnost: %d)",TowelRackMaker.maker.name,s),"success") end; return true end
function TowelRackMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function TowelRackMaker.build(id) local ok,e=TowelRackMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(TowelRackMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function TowelRackMaker.getQualityBonus() local b=0; for _,bd in ipairs(TowelRackMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function TowelRackMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and TowelRackMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and TowelRackMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and TowelRackMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and TowelRackMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and TowelRackMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and TowelRackMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and TowelRackMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and TowelRackMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #TowelRackMaker.buildings==0 then return false,"Potrebna vešalna delavnica" end; if not TowelRackMaker.maker then return false,"Potreben vesalkar" end; return true end
function TowelRackMaker.make(pt,qty) qty=qty or 1; local ok,e=TowelRackMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then TowelRackMaker.ironStock=TowelRackMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then TowelRackMaker.bronzeStock=TowelRackMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then TowelRackMaker.woodStock=TowelRackMaker.woodStock-d.woodCost*qty end; if d.leatherCost then TowelRackMaker.leatherStock=TowelRackMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then TowelRackMaker.silverStock=TowelRackMaker.silverStock-d.silverCost*qty end; if d.goldCost then TowelRackMaker.goldStock=TowelRackMaker.goldStock-d.goldCost*qty end; if d.jewelCost then TowelRackMaker.jewelStock=TowelRackMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then TowelRackMaker.pearlStock=TowelRackMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if TowelRackMaker.maker then t=math.max(1,t-math.floor(TowelRackMaker.maker.skill/13)) end; table.insert(TowelRackMaker.activeMaking,{id="towelrack_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function TowelRackMaker.completeMaking(m) local q=1.0+(TowelRackMaker.getQualityBonus()/100); if TowelRackMaker.maker then q=q+(TowelRackMaker.maker.skill/140) end; q=math.min(2.5,q); TowelRackMaker.productStock[m.productType]=(TowelRackMaker.productStock[m.productType] or 0)+m.quantity; TowelRackMaker.totalProducts=TowelRackMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if TowelRackMaker.maker then TowelRackMaker.maker.itemsMade=TowelRackMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then TowelRackMaker.maker.skill=math.min(100,TowelRackMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vešalka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"towelrack.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function TowelRackMaker.update(dt) if not _G.state then return end; TowelRackMaker.dayTimer=TowelRackMaker.dayTimer+dt; if TowelRackMaker.dayTimer>=30 then TowelRackMaker.dayTimer=0; for i=#TowelRackMaker.activeMaking,1,-1 do local m=TowelRackMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then TowelRackMaker.completeMaking(m); table.remove(TowelRackMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(TowelRackMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if TowelRackMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function TowelRackMaker.getStats() return {ironStock=TowelRackMaker.ironStock,bronzeStock=TowelRackMaker.bronzeStock,woodStock=TowelRackMaker.woodStock,leatherStock=TowelRackMaker.leatherStock,silverStock=TowelRackMaker.silverStock,goldStock=TowelRackMaker.goldStock,jewelStock=TowelRackMaker.jewelStock,pearlStock=TowelRackMaker.pearlStock,productStock=TowelRackMaker.productStock,numBuildings=#TowelRackMaker.buildings,hasMaker=TowelRackMaker.maker~=nil,makerName=TowelRackMaker.maker and TowelRackMaker.maker.name or "—",makerSkill=TowelRackMaker.maker and TowelRackMaker.maker.skill or 0,activeMaking=#TowelRackMaker.activeMaking,totalProducts=TowelRackMaker.totalProducts} end
return TowelRackMaker
